typedef struct {                       /* delegate: behaviour + its own state */
    void (*write)(void *self, const char *s);
    void *self;
} Sink;

typedef struct { Sink inner; size_t forwarded; } CountingSink;   /* wrapper */

static void counting_write(void *self, const char *s) {
    CountingSink *w = self;            /* C has no implicit this: downcast by hand */
    w->forwarded++;
    w->inner.write(w->inner.self, s);  /* forward the delegate's own self pointer */
}
